import { ReactNode } from 'react';
import { z } from 'zod';
// Remove imports of component types to avoid circular dependency

// 각 컴포넌트의 독립적인 props를 위한 스키마 정의

// 토큰과 은행 정보를 위한 기본 스키마
export const tokenValueSchema = z.object({
  value: z.string(),
  className: z.string().optional(),
});

export const bankValueSchema = z.object({
  value: z.string(),
  className: z.string().optional(),
});

// Asset 컴포넌트 스키마 - 자식 컴포넌트를 받도록 변경
export const assetSchema = z.object({
  children: z.custom<ReactNode>((value) => value !== null && value !== undefined, 'Must provide valid children'),
  className: z.string().optional(),
});

// Arrow 컴포넌트 스키마
export const transferArrowSchema = z.object({
  text: z.string().optional(),
  className: z.string().optional(),
});

// Wrapper 스키마
export const transferAssetInfoWrapperSchema = z.object({
  children: z.custom<ReactNode>((value) => value !== null && value !== undefined, 'Must provide valid children'),
  className: z.string().optional(),
});

// 편의성 컴포넌트를 위한 스키마
export const transferAssetInfoSchema = z.object({
  fromToken: z.string(),
  fromBank: z.string().optional(),
  toToken: z.string(),
  toBank: z.string().optional(),
});

// 타입 내보내기
export type TokenValueProps = z.infer<typeof tokenValueSchema> & {
  value: string;
};

export type BankValueProps = z.infer<typeof bankValueSchema> & {
  value: string;
};

export type AssetProps = z.infer<typeof assetSchema> & {
  children: ReactNode;
};

export type TransferArrowProps = z.infer<typeof transferArrowSchema> & {
  text?: string;
};

export type TransferAssetInfoWrapperProps = z.infer<typeof transferAssetInfoWrapperSchema> & {
  children: ReactNode;
};

export type TransferAssetInfoProps = z.infer<typeof transferAssetInfoSchema>;
